{"command":"$code = @'
using System;
using System.Runtime.InteropServices;
public class Win {
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, System.Text.StringBuilder lpString, int nCount);
    [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
    [DllImport("kernel32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
}
delegate bool EnumWindowsProc(IntPtr hwnd, IntPtr lParam);
'@; Add-Type $code; $sb = New-Object System.Text.StringBuilder 256; Win::EnumWindows({ param($hWnd, $lParam); [Win]::GetWindowText($hWnd, $sb, 256) | Out-Null; $title = $sb.ToString(); if ($title -match 'Lofi|YouTube|youtube') { Write-Output "Found: '$title'"; Win::ShowWindowAsync($hWnd, 9) | Out-Null } return $true }, [IntPtr]::Zero) | Out-Null","justification":"Enumerate all top-level windows and find any with YouTube/Lofi in title, then show them"}

