{"justification":"Maximize and bring to front all Edge browser processes, then find visible ones","command":"$code = @'
using System;
using System.Runtime.InteropServices;
public class W {
    [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
}
'@; Add-Type $code | Out-Null; Get-Process msedge -ErrorAction SilentlyContinue | ForEach-Object { if ($_.MainWindowHandle -ne [IntPtr]::Zero) { [W]::ShowWindowAsync($_.MainWindowHandle, 3) | Out-Null } }; Start-Sleep 2; Get-Process | Where-Object { $_.MainWindowHandle -ne [IntPtr]::Zero } | Select-Object ProcessName, Id, MainWindowTitle | Format-Table -AutoSize"}

