{"command":"$edgeProcs = [System.Diagnostics.Process]::GetProcessesByName("MicrosoftEdge"); Write-Output "Found $($edgeProcs.Length) Edge processes"; $showCode = @'
using System;
using System.Runtime.InteropServices;
public class W {
    [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
'@; Add-Type $showCode | Out-Null; foreach($ep in $edgeProcs) { if ($ep.MainWindowHandle.ToInt64() -gt 0) { [W]::ShowWindowAsync($ep.MainWindowHandle, 3) | Out-Null; Start-Sleep 0.5; [W]::SetForegroundWindow($ep.MainWindowHandle) | Out-Null; Write-Output "Maximized PID $($ep.Id)" } else { Write-Output "PID $($ep.Id): handle=$(($ep.MainWindowHandle).ToInt64())" }; }; Get-Process msedge,chrome -ErrorAction SilentlyContinue | ForEach-Object { Write-Output "$($_.ProcessName) PID $($_.Id) Handle=$([System.Convert]::ToInt64($_.MainWindowHandle)) CPU=$([math]::Round($_.CPU,1))" }","justification":"Get all Edge processes via .NET, try maximizing each one's window, and report handles with their integer values"}

{"command":"$env:Path = [Environment]::GetEnvironmentVariable("PATH", "Machine") + ";" + [Environment]::GetEnvironmentVariable("PATH", "User"); $code = @'
using System;
using System.Runtime.InteropServices;
public class Finder {
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nCount);
    [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
    [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
public delegate bool EnumWindowsProc(IntPtr hwnd, IntPtr lParam);
'@; Add-Type $code | Out-Null; Write-Output "Enumerating windows..."; $found = New-Object System.Collections.ArrayList; Finder::EnumWindows({ param($hWnd, $lParam); $pid = 0u; [Finder]::GetWindowThreadProcessId($hWnd, [ref]$pid) | Out-Null; if ($pid -in @(4532,6964,7164,8048,23280,25260,26540,27856,29776,30744,32216,33656,35576,37896,37928,38336,38848)) { $sb = New-Object System.Text.StringBuilder 256; [Finder]::GetWindowText($hWnd, $sb, 256) | Out-Null; $title = $sb.ToString(); if ($title.Length -gt 0) { $null = $found.Add("PID=$pid Title='$title' Handle=$([IntPtr]::ToIntPtr($hWnd).ToInt64())") }; [Finder]::ShowWindowAsync($hWnd, 3) | Out-Null; Start-Sleep 0.5; [Finder]::SetForegroundWindow($hWnd) | Out-Null } return $true }, [IntPtr]::Zero) | Out-Null; if ($found.Count -gt 0) { Write-Output ("Found " + $found.Count + " windows"); foreach($w in $found) { Write-Output " " + $w } } else { Write-Output "No matching window handles found" }; Write-Output "Done!"","justification":"Use EnumWindows to find all Edge windows by PID, get their titles, maximize them and bring to foreground"}
